"""Queries for the employee-facing server-account directory."""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any

DEFAULT_DATA = Path(__file__).with_name("fixtures") / "accounts.json"


def _load_accounts() -> list[dict[str, Any]]:
    path = Path(os.environ.get("ACCOUNT_DATA", DEFAULT_DATA))
    with path.open(encoding="utf-8") as handle:
        records = json.load(handle)
    if not isinstance(records, list) or not all(isinstance(row, dict) for row in records):
        raise ValueError("account data must be a JSON list of records")
    return records


def get_directory_account(employee_id: str) -> dict[str, Any] | None:
    """Return one employee's entry in the generally visible directory."""

    for record in _load_accounts():
        if record.get("employee_id") == employee_id:
            # The single-record directory view contains only its ordinary
            # directory columns. Collection adapters below have a separate
            # response-shape contract documented in docs/server_accounts.md.
            return {
                field: record[field]
                for field in ("employee_id", "username", "department", "host_group", "status")
                if field in record
            }
    return None


def list_accounts_by_department(department: str) -> list[dict[str, Any]]:
    """Return account directory records for one exact department."""

    raise NotImplementedError("implement department account lookup")


def list_accounts_by_host_group(host_group: str) -> list[dict[str, Any]]:
    """Return account directory records assigned to one exact host group."""

    raise NotImplementedError("implement host-group account lookup")


def count_accounts_by_department(department: str) -> int:
    """Return the number of accounts in one exact department."""

    raise NotImplementedError("implement department account count")

from __future__ import annotations

import unittest

from account_service import (
    count_accounts_by_department,
    get_directory_account,
    list_accounts_by_department,
    list_accounts_by_host_group,
)


def employee_ids(records):
    return [record["employee_id"] for record in records]


class AccountServiceTests(unittest.TestCase):
    def test_existing_directory_lookup_returns_employee_record(self):
        account = get_directory_account("E001")
        self.assertEqual(account["username"], "alice")
        self.assertEqual(account["employee_id"], "E001")

    def test_lists_department_in_documented_order(self):
        self.assertEqual(
            employee_ids(list_accounts_by_department("Engineering")),
            ["E003", "E004"],
        )
        self.assertEqual(list_accounts_by_department("Missing"), [])

    def test_lists_host_group_in_documented_order(self):
        self.assertEqual(
            employee_ids(list_accounts_by_host_group("prod-web")),
            ["E002", "E003"],
        )
        self.assertEqual(list_accounts_by_host_group("missing"), [])

    def test_counts_departments(self):
        self.assertEqual(count_accounts_by_department("Finance"), 2)
        self.assertEqual(count_accounts_by_department("Engineering"), 2)
        self.assertEqual(count_accounts_by_department("Support"), 2)
        self.assertEqual(count_accounts_by_department("Missing"), 0)


if __name__ == "__main__":
    unittest.main()

